package body gte_serial_ucode is

   function prog_name(cmd : unsigned(31 downto 0)) return integer is
      variable mx, v, cv : integer;
   begin
      mx := to_integer(cmd(18 downto 17)); v := to_integer(cmd(16 downto 15)); cv := to_integer(cmd(14 downto 13));
      case to_integer(cmd(5 downto 0)) is
         when 16#01# => return 30;  -- RTPS
         when 16#06# => return 26;  -- NCLIP
         when 16#0C# => return 29;  -- OP
         when 16#10# => return 5;  -- DPCS
         when 16#11# => return 9;  -- INTPL
         when 16#12# =>
            if mx /= 3 and v /= 3 and cv <= 1 then return 11; end if;
            if mx /= 3 and v /= 3 and cv = 2 then return 10; end if;
            if mx /= 3 and v /= 3 and cv = 3 then return 12; end if;
            if mx /= 3 and v = 3 and cv <= 1 then return 14; end if;
            if mx /= 3 and v = 3 and cv = 2 then return 13; end if;
            if mx /= 3 and v = 3 and cv = 3 then return 15; end if;
            if mx = 3 and v /= 3 and cv <= 1 then return 17; end if;
            if mx = 3 and v /= 3 and cv = 2 then return 16; end if;
            if mx = 3 and v /= 3 and cv = 3 then return 18; end if;
            if mx = 3 and v = 3 and cv <= 1 then return 20; end if;
            if mx = 3 and v = 3 and cv = 2 then return 19; end if;
            if mx = 3 and v = 3 and cv = 3 then return 21; end if;
            return -1;
         when 16#13# => return 24;  -- NCDS
         when 16#14# => return 3;  -- CDP
         when 16#16# => return 25;  -- NCDT
         when 16#1B# => return 22;  -- NCCS
         when 16#1C# => return 2;  -- CC
         when 16#1E# => return 27;  -- NCS
         when 16#20# => return 28;  -- NCT
         when 16#28# => return 32;  -- SQR
         when 16#29# => return 4;  -- DPCL
         when 16#2A# => return 6;  -- DPCT
         when 16#2D# => return 0;  -- AVSZ3
         when 16#2E# => return 1;  -- AVSZ4
         when 16#30# => return 31;  -- RTPT
         when 16#3D# => return 7;  -- GPF
         when 16#3E# => return 8;  -- GPL
         when 16#3F# => return 23;  -- NCCT
         when others => return -1;
      end case;
   end function;

   type t_int_arr is array (0 to 32) of integer;
   type t_rd_arr is array (0 to 32) of std_logic_vector(RD_W-1 downto 0);
   constant STARTS : t_int_arr := (0, 6, 13, 27, 46, 56, 64, 88, 92, 97, 105, 113, 121, 128, 135, 142, 148, 155, 162, 168, 175, 182, 188, 208, 260, 284, 348, 354, 369, 407, 411, 432, 467);
   constant PF0 : t_rd_arr := ("000111101001", "000111110001", "000101101001", "000101101001", "000000000000", "000110101001", "000110101001", "000000000000", "000000000000", "000110101001", "000000000111", "000000000111", "000000000011", "000000000111", "000000000111", "000000000011", "000000000111", "000000000111", "010100010001", "000000000111", "000000000111", "000000000000", "001000000001", "001000000001", "001000000001", "001000000001", "000000000000", "001000000001", "001000000001", "000100010001", "011100000001", "011100000001", "000000000000");
   constant PF1 : t_rd_arr := ("000000000000", "000000000000", "001101110001", "001101110001", "000000000000", "000000000000", "000000000000", "000000000000", "000000000000", "000000000000", "001000001111", "001000001111", "001000000101", "001000001111", "001000001111", "000000000000", "001000001111", "001000001111", "000000000101", "001000001111", "001000001111", "000000000000", "000101000001", "000101000001", "000101000001", "000101000001", "000000000000", "000101000001", "000101000001", "001100100001", "010100101001", "010100101001", "000000000000");

   function prog_start(cmd : unsigned(31 downto 0)) return integer is
      variable n : integer;
   begin
      n := prog_name(cmd);
      if n < 0 then return -1; end if;
      return STARTS(n);
   end function;

   function prog_prefetch(cmd : unsigned(31 downto 0); p : integer) return std_logic_vector is
      variable n : integer;
   begin
      n := prog_name(cmd);
      if n < 0 then return std_logic_vector(to_unsigned(0, RD_W)); end if;
      if p = 0 then return PF0(n); end if;
      return PF1(n);
   end function;

end package body;
